import { jsPDF } from "jspdf";

// REPLACE THIS STRING WITH YOUR ACTUAL BASE64 IMAGE STRING
const LOGO_BASE64 = ""; 

export const downloadCertificate = (userName, courseTitle) => {
  // 1. Create Document (Landscape A4)
  const doc = new jsPDF({
    orientation: "landscape",
    unit: "mm",
    format: "a4"
  });

  const width = doc.internal.pageSize.getWidth();
  const height = doc.internal.pageSize.getHeight();

  // --- BACKGROUND & BORDER ---
  // White Background
  doc.setFillColor(255, 255, 255);
  doc.rect(0, 0, width, height, "F");

  // Ornamental Border (Double Line)
  // Outer Blue Line
  doc.setLineWidth(1.5);
  doc.setDrawColor(37, 99, 235); // Tailwind Blue-600
  doc.rect(10, 10, width - 20, height - 20);

  // Inner Gold Line
  doc.setLineWidth(0.5);
  doc.setDrawColor(234, 179, 8); // Tailwind Yellow-500 (Gold)
  doc.rect(13, 13, width - 26, height - 26);

  // --- LOGO ---
  // Centered at the top
  const logoSize = 40; // Adjust size as needed
  try {
    // x calculation centers the image: (pageWidth / 2) - (imageWidth / 2)
    doc.addImage(LOGO_BASE64, 'JPEG', (width / 2) - (logoSize / 2), 20, logoSize, logoSize);
  } catch (e) {
    console.error("Logo error", e);
  }

  // --- TEXT CONTENT ---
  
  // Helper to center text
  const centerText = (text, y, size, font, color = [0, 0, 0], weight = "normal") => {
    doc.setFont(font, weight);
    doc.setFontSize(size);
    doc.setTextColor(...color);
    doc.text(text, width / 2, y, { align: "center" });
  };

  // 1. Title
  // Shifted down slightly to make room for the logo
  centerText("CERTIFICATE", 75, 40, "times", [37, 99, 235], "bold"); // Blue
  centerText("OF ACHIEVEMENT", 88, 16, "times", [100, 100, 100], "normal"); // Gray

  // 2. Presentation Text
  centerText("This is to certify that", 105, 14, "helvetica", [120, 120, 120]);

  // 3. Student Name (Big, Elegant)
  centerText(userName.toUpperCase(), 125, 32, "times", [0, 0, 0], "bold");
  
  // Underline for Name
  doc.setDrawColor(37, 99, 235);
  doc.setLineWidth(0.5);
  doc.line((width / 2) - 60, 128, (width / 2) + 60, 128);

  // 4. Achievement Text
  centerText("Has successfully demonstrated mastery in", 145, 14, "helvetica", [120, 120, 120]);

  // 5. Course Title (Prominent)
  centerText(courseTitle, 160, 24, "helvetica", [37, 99, 235], "bold");

  // --- FOOTER & SIGNATURE ---
  const date = new Date().toLocaleDateString(undefined, { year: 'numeric', month: 'long', day: 'numeric' });
  // Adjusted Y position for footer elements
  const lineY = 185; 

  // Date (Left)
  doc.setFont("helvetica", "normal");
  doc.setFontSize(12);
  doc.setTextColor(50, 50, 50);
  doc.text(date, 50, lineY - 5, { align: "center" }); // Date above line

  doc.setDrawColor(150, 150, 150);
  doc.setLineWidth(0.5);
  doc.line(30, lineY, 70, lineY); // Line

  doc.setFontSize(10);
  doc.setTextColor(150, 150, 150);
  doc.text("Date Issued", 50, lineY + 6, { align: "center" }); // Label below line

  // Signature (Right)
  doc.setFont("times", "italic"); 
  doc.setFontSize(18);
  doc.setTextColor(0, 0, 0);
  doc.text("SkillForge AI", width - 50, lineY - 3, { align: "center" }); // Signature above line
  
  doc.setDrawColor(150, 150, 150);
  doc.line(width - 70, lineY, width - 30, lineY); // Line
  
  doc.setFont("helvetica", "normal");
  doc.setFontSize(10);
  doc.setTextColor(150, 150, 150);
  doc.text("Verified Signature", width - 50, lineY + 6, { align: "center" }); // Label below line

  // 6. ID Watermark (Subtle)
  const id = `ID: ${Math.random().toString(36).substr(2, 9).toUpperCase()}`;
  doc.setFontSize(8);
  doc.setTextColor(200, 200, 200);
  doc.text(id, width / 2, height - 10, { align: "center" });

  // Save File
  doc.save(`${courseTitle.replace(/\s+/g, '_')}_Certificate.pdf`);
};